  emailMetadata?: z.infer<typeof PropertyMetadataSchema>
  emailNotification?: z.infer<typeof RecipientEmailNotificationSchema>
  emailRecipientPostSigningURL?: string
  embeddedRecipientStartURL?: string
  errorDetails?: z.infer<typeof ErrorDetailsSchema>
  excludedDocuments?: string[]
  faxNumber?: string
  faxNumberMetadata?: z.infer<typeof PropertyMetadataSchema>
  firstName?: string
  firstNameMetadata?: z.infer<typeof PropertyMetadataSchema>
  fullName?: string
  fullNameMetadata?: z.infer<typeof PropertyMetadataSchema>
  idCheckConfigurationName?: string
  idCheckConfigurationNameMetadata?: z.infer<typeof PropertyMetadataSchema>
  idCheckInformationInput?: z.infer<typeof IdCheckInformationInputSchema>
  identityVerification?: z.infer<typeof RecipientIdentityVerificationSchema>
  inheritEmailNotificationConfiguration?: string
  lastName?: string
  lastNameMetadata?: z.infer<typeof PropertyMetadataSchema>
  lockedRecipientPhoneAuthEditable?: string
  lockedRecipientSmsEditable?: string
  name?: string
  nameMetadata?: z.infer<typeof PropertyMetadataSchema>
  note?: string
  noteMetadata?: z.infer<typeof PropertyMetadataSchema>
  phoneAuthentication?: z.infer<typeof RecipientPhoneAuthenticationSchema>
  phoneNumber?: z.infer<typeof RecipientPhoneNumberSchema>
  recipientAttachments?: z.infer<typeof RecipientAttachmentSchema>[]
  recipientAuthenticationStatus?: z.infer<typeof AuthenticationStatusSchema>
  recipientFeatureMetadata?: z.infer<typeof FeatureAvailableMetadataSchema>[]
  recipientId?: string
  recipientIdGuid?: string
  recipientType?: string
  recipientTypeMetadata?: z.infer<typeof PropertyMetadataSchema>
  requireIdLookup?: string
  requireIdLookupMetadata?: z.infer<typeof PropertyMetadataSchema>
