const RecipientViewRequestSchema = z
  .object({
    assertionId: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'A unique identifier of the authentication event executed by the client application.',
      }),
    authenticationInstant: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'A sender-generated value that indicates the date and time that the signer was authenticated.',
      }),
    authenticationMethod: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Required. Choose a value that most closely matches the technique your application used to authenticate the recipient / signer. \n\nChoose a value from this list: \n* Biometric \n* Email\n* HTTPBasicAuth\n* Kerberos\n* KnowledgeBasedAuth\n* None\n* PaperDocuments\n* Password\n* RSASecureID\n* SingleSignOn_CASiteminder\n* SingleSignOn_InfoCard\n* SingleSignOn_MicrosoftActiveDirectory\n* SingleSignOn_Other\n* SingleSignOn_Passport\n* SingleSignOn_SAML\n* Smartcard\n* SSLMutualAuth\n* X509Certificate\n\nThis information is included in the Certificate of Completion.',
      }),
    clientURLs: RecipientTokenClientURLsSchema.exactOptional(),
    clientUserId: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "A sender-created value. If provided, the recipient is treated as an embedded (captive) recipient or signer.\n\nUse your application's client ID (user ID) for the recipient. Doing so enables the details of your application's authentication of the recipient to be connected to the recipient's signature if the signature is disputed or repudiated.\n\nMaximum length: 100 characters.",
      }),
    email: z
      .string()
      .exactOptional()
      .openapi({
        description:
          '(Required) Specifies the email of the recipient. You can use either `email` and `userName` or `userId` to identify the recipient.',
      }),
    frameAncestors: z.array(z.string()).exactOptional().openapi({ description: '' }),
    messageOrigins: z.array(z.string()).exactOptional().openapi({ description: '' }),
    pingFrequency: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Only used if `pingUrl` is specified. This is the interval, in seconds, between pings on the `pingUrl`.  The default is `300` seconds. Valid values are 60-1200 seconds.',
      }),
    pingUrl: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The client URL that the DocuSign Signing experience should ping to indicate to the client that Signing is active. An HTTP GET call is executed against the client. The response from the client is ignored. The intent is for the client to reset its session timer when the request is received.',
      }),
    recipientId: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Unique for the recipient. It is used by the tab element to indicate which recipient is to sign the Document.',
      }),
    returnUrl: z
      .string()
      .exactOptional()
      .openapi({
        description:
          '(Required) The URL to which the user should be redirected\nafter the signing session has ended.\n\nMaximum Length: 470 characters. If the `returnUrl` exceeds this\nlimit, the user is redirected to a truncated URL\nBe sure to include `https://` in the URL\nor redirecting might fail on some browsers.\n\n\nWhen DocuSign redirects to\nthis URL, it will include an `event` query parameter that your app can use:\n\n* `access_code_failed`: Recipient used incorrect access code.\n* `cancel`: Recipient canceled the signing operation,\n  possibly by using the **Finish Later** option.\n* `decline`: Recipient declined to sign.\n* `exception`: A system error occurred during the signing process.\n* `fax_pending`: Recipient has a fax pending.\n* `id_check_failed`: Recipient failed an ID check.\n* `session_timeout`: The session timed out. An account can control this timeout by using the **Signer Session Timeout** option.\n* `signing_complete`: The recipient completed the signing ceremony.\n* `ttl_expired`: The Time To Live token for the envelope has expired.\n  After being successfully invoked, these tokens expire\n  after 5 minutes or if the envelope is voided.\n* `viewing_complete`: The recipient completed viewing an envelope\n  that is in a read-only/terminal state,\n  such as completed, declined, or voided.\n\n',
      }),
    securityDomain: z
      .string()
      .exactOptional()
      .openapi({ description: 'The domain in which the user authenticated.' }),
    userId: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The user ID of the recipient. You can use either the user ID or email and user name to identify the recipient. \n\nIf `userId` is used and a `clientUserId` is provided, the value in the `userId` property must match a `recipientId` (which you can retrieve with a GET recipients call) for the envelope. \n\nIf a `userId` is used and a `clientUserId` is not provided, the `userId` must match the user ID of the authenticating user.',
      }),
    userName: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The username of the recipient. You can use either `email` and `userName` or `userId` to identify the recipient.',
      }),
    xFrameOptions: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Specifies whether a browser should be allowed to render a page in a frame or IFrame. Setting this property ensures that your content is not embedded into unauthorized pages or frames.\n\nValid values are:\n\n- `deny`: The page cannot be displayed in a frame.\n- `same_origin`: The page can only be displayed in a frame on the same origin as the page itself.\n- `allow_from`: The page can only be displayed in a frame on the origin specified by the `xFrameOptionsAllowFromUrl` property.',
      }),
    xFrameOptionsAllowFromUrl: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'When the value of `xFrameOptions` is `allow_from`, this property specifies the origin on which the page is allowed to display in a frame. If the value of `xFrameOptions` is `allow_from`, you must include a value for this property.',
      }),
  })
  .openapi({
    description:
      'The request body for the [EnvelopeViews: createRecipient](/docs/esign-rest-api/reference/envelopes/envelopeviews/createrecipient/)\nand\n[EnvelopeViews: createSharedRecipient](/docs/esign-rest-api/reference/envelopes/envelopeviews/createsharedrecipient/) methods.',
    'x-ds-definition-name': 'recipientViewRequest',
    'x-ms-summary':
      'The request body for the [EnvelopeViews: createRecipient](/docs/esign-rest-api/reference/envelopes/envelopeviews/createrecipient/)\nand\n[EnvelopeViews: createSharedRecipient](/docs/esign-rest-api/reference/envelopes/envelopeviews/createsharedrecipient/) methods.',
    required: [],
  })
  .openapi('RecipientViewRequest')

