const TemplateRoleSchema: z.ZodType<TemplateRoleType> = z
  .object({
    accessCode: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "If a value is provided, the recipient must enter the value as the access code to view and sign the envelope. \n\nMaximum Length: 50 characters and it must conform to the account's access code format setting.\n\nIf blank, but the signer `accessCode` property is set in the envelope, then that value is used.\n\nIf blank and the signer `accessCode` property is not set, then the access code is not required.",
      }),
    additionalNotifications: z
      .array(RecipientAdditionalNotificationSchema)
      .exactOptional()
      .openapi({ description: 'An array of additional notification objects.' }),
    clientUserId: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Specifies whether the recipient is embedded or remote. \n\nIf the `clientUserId` property is not null then the recipient is embedded. Use this field to associate the signer with their userId in your app. Authenticating the user is the responsibility of your app when you use embedded signing.\n\nIf the `clientUserId` property is set and either `SignerMustHaveAccount` or `SignerMustLoginToSign` property of the account settings is set to  **true,** an error is generated on sending.\n\n**Note:** This property is not returned by the [listStatusChanges](/docs/esign-rest-api/reference/envelopes/envelopes/liststatuschanges/) endpoint.\n\nMaximum length: 100 characters. \n',
      }),
    defaultRecipient: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'When **true,** this recipient is the default recipient and any tabs generated by the `transformPdfFields` option are mapped to this recipient.',
      }),
    deliveryMethod: z.string().exactOptional().openapi({ description: 'Reserved for DocuSign.' }),
    email: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The email address of the person associated with a role name. It is the email address of the person specified in the `name` property.\n\nFor an in-person signer, this is the email address of the host.',
      }),
    emailNotification: RecipientEmailNotificationSchema.exactOptional(),
    embeddedRecipientStartURL: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "Specifies a sender-provided valid URL string for redirecting an embedded recipient. When using this option, the embedded recipient still receives an email from DocuSign, just as a remote recipient would. When the document link in the email is clicked the recipient is redirected, through DocuSign, to the supplied URL to complete their actions. When routing to the URL, the sender's system (the server responding to the URL) must request a recipient token to launch a signing session. \n\nWhen `SIGN_AT_DOCUSIGN`, the recipient is directed to an embedded signing or viewing process directly at DocuSign. The signing or viewing action is initiated by the DocuSign system and the transaction activity and Certificate of Completion records will reflect this. In all other ways the process is identical to an embedded signing or viewing operation launched by a partner.\n\nIt is important to understand that in a typical embedded workflow, the authentication of an embedded recipient is the responsibility of the sending application. DocuSign expects that senders will follow their own processes for establishing the recipient's identity. In this workflow the recipient goes through the sending application before the embedded signing or viewing process is initiated. However, when the sending application sets `EmbeddedRecipientStartURL=SIGN_AT_DOCUSIGN`, the recipient goes directly to the embedded signing or viewing process, bypassing the sending application and any authentication steps the sending application would use. In this case, DocuSign recommends that you use one of the normal DocuSign authentication features (Access Code, Phone Authentication, SMS Authentication, etc.) to verify the identity of the recipient.\n\nIf the `clientUserId` property is NOT set, and the `embeddedRecipientStartURL` is set, DocuSign will ignore the redirect URL and launch the standard signing process for the email recipient. Information can be appended to the embedded recipient start URL using merge fields. The available merge fields items are: `envelopeId`, `recipientId`, `recipientName`, `recipientEmail`, and `customFields`. The `customFields` property must be set for the recipient or envelope. The merge fields are enclosed in double brackets. \n\n*Example*: \n\n`http://senderHost/[[mergeField1]]/ beginSigningSession? [[mergeField2]]&[[mergeField3]]` ",
      }),
    inPersonSignerName: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The full legal name of the in-person signer.\n\nMaximum Length: 100 characters.',
      }),
    name: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "Specifies the recipient's name.\n\nFor an in-person signer, this is the name of the host.",
      }),
    phoneNumber: RecipientPhoneNumberSchema.exactOptional(),
    recipientSignatureProviders: z
      .array(RecipientSignatureProviderSchema)
      .exactOptional()
      .openapi({
        description:
          'The default signature provider is the DocuSign Electronic signature system. This parameter is used to specify one or more Standards Based Signature (digital signature) providers for the signer to use. [More information.](/docs/esign-rest-api/esign101/concepts/standards-based-signatures/)',
      }),
    roleName: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Optional element. Specifies the role name associated with the recipient.<br/><br/>This property is required when you are working with template recipients.',
      }),
    routingOrder: z
      .string()
      .exactOptional()
      .openapi({ description: 'Specifies the routing order of the recipient in the envelope. ' }),
    signingGroupId: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The ID of the [signing group](https://support.docusign.com/en/guides/ndse-user-guide-signing-groups).\n',
      }),
    tabs: EnvelopeRecipientTabsSchema.exactOptional(),
  })
  .openapi({
    description: 'Information about a specific role.',
    'x-ds-definition-name': 'templateRole',
    'x-ms-summary': 'Information about a specific role.',
    required: [],
  })
  .openapi('TemplateRole')

