const TemplateLocksSchema = z
  .object({
    errorDetails: ErrorDetailsSchema.exactOptional(),
    lockDurationInSeconds: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The number of seconds until the lock expires when there is no activity on the template.\n\nIf no value is entered, then the default value of 300 seconds is used. The maximum value is 1,800 seconds.\n\nThe lock duration can be extended.\n',
      }),
    lockToken: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'A unique identifier provided to the owner of the lock. You must use this token with subsequent calls to prove ownership of the lock.',
      }),
    lockType: z
      .string()
      .exactOptional()
      .openapi({ description: 'The type of lock.  Currently `edit` is the only supported type.' }),
    lockedByApp: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Specifies the friendly name of  the application that is locking the envelope.',
      }),
    lockedByUser: UserInfoSchema.exactOptional(),
    lockedUntilDateTime: z
      .string()
      .exactOptional()
      .openapi({ description: 'The date and time that the lock expires.' }),
    useScratchPad: z
      .string()
      .exactOptional()
      .openapi({ description: 'When **true,** a scratchpad is used to edit information.\n ' }),
  })
  .openapi({
    description:
      'This section provides information about template locks. You use template locks to prevent others from making changes to a template while you are modifying it.',
    'x-ds-category': 'Templates',
    'x-ds-definition-name': 'lockInformation',
    'x-ds-order': '80',
    'x-ms-summary':
      'This section provides information about template locks. You use template locks to prevent others from making changes to a template while you are modifying it.',
    required: [],
  })
  .openapi('TemplateLocks')

const TemplateRecipientTabsSchema: z.ZodType<TemplateRecipientTabsType> = z
