            description:
              'If missing or any value other than `-1`, the returned list contains only the top-level folders.\nA value of `-1` returns the complete folder hierarchy.\n',
            in: 'query',
            name: 'sub_folder_depth',
            required: false,
            schema: { type: 'string' },
